 63 | void awts_draw_text(AwtsBrowserState* state, float x, float y, const char* text, float r, float g, float b) {
 64 |   if (!state->font.ready || !text) return;
 65 |   glColor3f(r, g, b);
 66 |   glRasterPos2f(x, y);
 67 |   glPushAttrib(GL_LIST_BIT);
 68 |   glListBase(state->font.base);
 69 |   glCallLists((GLsizei)strlen(text), GL_UNSIGNED_BYTE, text);
 70 |   glPopAttrib();
