 91 | static AwtsDomNode* find_node(AwtsBrowserState* state, const char* tag, const char* id) {
 92 |   for (int i = 0; i < state->dom.count; i++) {
 93 |     AwtsDomNode* n = &state->dom.nodes[i];
 94 |     if (tag && strcmp(n->tag, tag)) continue;
 95 |     if (id && strcmp(n->id, id)) continue;
 96 |     return n;
 97 |   }
 98 |   return NULL;
