102 |   rect(x, y, w, h, 0.07f, 0.10f, 0.14f);
103 |   outline(x, y, w, h, 0.12f, 0.34f, 0.72f);
104 | 
105 |   /* This is the page canvas rendering. It remains a minimal WebGL bridge result,
