142 | static int draw_executor_stream(AwtsBrowserState* state) {
143 |   const char* stream = AWTS_NATIVE_RENDER_STREAM;
144 |   if (!stream || !*stream) return 0;
145 |   char* copy = _strdup(stream);
146 |   if (!copy) return 0;
147 |   float ox = sx(state, 96), oy = sy(state, 150);
148 |   float scaleX = sw(state, 2), scaleY = -sh(state, 2);
149 |   for (char* line = copy; line && *line;) {
150 |     char* next = strchr(line, '\n');
151 |     if (next) *next++ = 0;
152 |     char kind[16], id[16], a[64], b[64], c[160], d[64], e[64];
153 |     char* at = line;
154 |     memset(kind, 0, sizeof(kind)); memset(id, 0, sizeof(id));
155 |     memset(a, 0, sizeof(a)); memset(b, 0, sizeof(b)); memset(c, 0, sizeof(c));
156 |     memset(d, 0, sizeof(d)); memset(e, 0, sizeof(e));
157 |     next_part(&at, kind, sizeof(kind)); next_part(&at, id, sizeof(id));
158 |     next_part(&at, a, sizeof(a)); next_part(&at, b, sizeof(b));
159 |     next_part(&at, c, sizeof(c)); next_part(&at, d, sizeof(d)); next_part(&at, e, sizeof(e));
160 |     if (!strcmp(kind, "BOX")) {
161 |       float r, g, blue; hex_color(e, &r, &g, &blue);
162 |       rect(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, r, g, blue);
163 |       outline(ox + atof(a) * scaleX, oy + atof(b) * scaleY, atof(c) * scaleX, atof(d) * scaleY, 0.70f, 0.72f, 0.78f);
164 |     } else if (!strcmp(kind, "TEXT")) {
165 |       float r, g, blue; hex_color(d, &r, &g, &blue);
166 |       awts_draw_text(state, ox + atof(a) * scaleX, oy + atof(b) * scaleY, c, r, g, blue);
167 |     } else if (!strcmp(kind, "WEBGL")) {
168 |       rect(sx(state, 470), sy(state, 180 + atoi(id) * 18), sw(state, 220), -sh(state, 10), 0.10f, 0.18f, 0.32f);
169 |     }
170 |     line = next;
171 |   }
172 |   free(copy);
173 |   return 1;
174 | }
