196 | void awts_draw_native_browser(AwtsBrowserState* state) {
197 |   glViewport(0, 0, state->width, state->height);
198 |   glClearColor(0.80f, 0.82f, 0.86f, 1.0f);
199 |   glClear(GL_COLOR_BUFFER_BIT);
200 | 
201 |   draw_browser_chrome(state);
202 |   if (!strcmp(state->pageTitle, "/index.html") && draw_executor_stream(state)) return;
203 |   if (!strcmp(state->pageTitle, "/index.html") && state->dom.count > 0) draw_embedded_app(state);
204 |   else draw_loaded_text_page(state);
